-- M5: voice-agent lexicon. Spoken EN / Tamil / Tanglish synonyms per taxonomy node (data, admin-editable).
CREATE OR REPLACE FUNCTION pg_temp.syn(_slug text, _s text[]) RETURNS void LANGUAGE sql AS $$
  UPDATE public.taxonomy_nodes SET synonyms = ARRAY(SELECT DISTINCT unnest(COALESCE(synonyms,'{}') || _s)) WHERE slug = _slug $$;
